Clase Figura
    Publico Metodo Area() Como Real
        Retornar 0.0;
    FinMetodo
FinClase

Clase Cuadrado Hereda De Figura
    Privado Definir lado Como Entero;

    Metodo Constructor(unLado Como Entero)
        Este.lado <- unLado;
    FinMetodo

    Publico Metodo Area() Como Real
        Retornar Este.lado * Este.lado;
    FinMetodo
FinClase

Clase Circulo Hereda De Figura
    Privado Definir radio Como Entero;

    Metodo Constructor(unRadio Como Entero)
        Este.radio <- unRadio;
    FinMetodo

    Publico Metodo Area() Como Real
        Retornar Este.radio * Este.radio * 3.14;
    FinMetodo
FinClase

Proceso SumarAreas
    Dimension figuras[2] Como Figura;
    Definir lado Como Entero;
    Definir radio Como Entero;
    Definir i Como Entero;
    Definir total Como Real;
    Leer lado;
    Leer radio;
    figuras[0] <- Nuevo Cuadrado(lado);
    figuras[1] <- Nuevo Circulo(radio);
    total <- 0.0;
    Para i <- 0 Hasta 1 Con Paso 1 Hacer
        total <- total + figuras[i].Area();
    FinPara
    Escribir total;
FinProceso
